#include <iostream>
#include <vector>

void printArr(std::vector<int> arr)
{
    for (int x : arr)
    {
        std::cout << x << " ";
    }
    std::cout << "\n";
}

void insertionSort(std::vector<int> &arr)
{
    // loop passes
    for (int i = 1; i < arr.size(); i++)
    {
        // loop for each pass
        int j = i - 1;
        int key = arr[i];
        while (j >= 0 && arr[j] > key)
        {
            int temp = arr[j + 1];
            arr[j + 1] = arr[j];
            arr[j] = temp;
            j--;
        }
    }
    std::cout << "Sorting done!!\n";
}

